diff --git a/src/liblzma/lz/lz_decoder.c b/src/liblzma/lz/lz_decoder.c
index 6dc4cef..9678d2a 100644
--- a/src/liblzma/lz/lz_decoder.c
+++ b/src/liblzma/lz/lz_decoder.c
@@ -243,8 +243,16 @@ lzma_lz_decoder_init(lzma_next_coder *next, const lzma_allocator *allocator,
 	// Allocate and initialize the LZ-based decoder. It will also give
 	// us the dictionary size.
 	lzma_lz_options lz_options;
-	return_if_error(lz_init(&coder->lz, allocator,
-			filters[0].id, filters[0].options, &lz_options));
+	const lzma_ret lz_ret = lz_init(&coder->lz, allocator,
+			filters[0].id, filters[0].options, &lz_options);
+	if (lz_ret != LZMA_OK) {
+		// If the LZ-specific initialization fails, forget the
+		// dictionary size so that a later reinitialization of this
+		// coder reallocates the dictionary buffer instead of reusing
+		// a possibly stale one.
+		coder->dict.size = 0;
+		return lz_ret;
+	}

 	// If the dictionary size is very small, increase it to 4096 bytes.
 	// This is to prevent constant wrapping of the dictionary, which
@@ -278,7 +286,6 @@ lzma_lz_decoder_init(lzma_next_coder *next, const lzma_allocator *allocator,

 	// Allocate and initialize the dictionary.
 	if (coder->dict.size != alloc_size) {
-		coder->dict.size = 0;
 		lzma_free(coder->dict.buf, allocator);

